package com.hbm.satellite.link.client;
import com.hbm.client.gui.font.LegacyFonts;import com.hbm.satellite.link.*;import net.minecraft.ChatFormatting;import net.minecraft.client.Minecraft;import net.minecraft.network.chat.Component;import net.minecraft.world.phys.BlockHitResult;import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.client.event.RenderGuiLayerEvent;import net.neoforged.neoforge.client.gui.VanillaGuiLayers;
/** Original ILookOverlay title/shadow and10pixeltext lines, no invented standalone/menu screen. */
@EventBusSubscriber(modid="hbm",value=Dist.CLIENT)public final class SatelliteLinkOverlay{
 @SubscribeEvent public static void render(RenderGuiLayerEvent.Pre event){if(!event.getName().equals(VanillaGuiLayers.CROSSHAIR))return;var mc=Minecraft.getInstance();if(mc.options.hideGui||mc.level==null||!(mc.hitResult instanceof BlockHitResult hit)||!(mc.level.getBlockState(hit.getBlockPos()).getBlock() instanceof SatelliteLinkBlock block))return;var pos=block.findCore(mc.level,hit.getBlockPos());if(pos==null||!(mc.level.getBlockEntity(pos) instanceof SatelliteLinkBlockEntity link))return;var graphics=event.getGuiGraphics();var font=LegacyFonts.get();int x=graphics.guiWidth()/2+8,y=graphics.guiHeight()/2;var title=Component.translatable("block.hbm.machine_satlink");graphics.drawString(font,title,x+1,y-9,0x404000,false);graphics.drawString(font,title,x,y-10,0xffff00,false);graphics.drawString(font,Component.translatable("tile.machine_satlink.freq").append(": "+link.freq),x,y,0xffffff,true);y+=10;graphics.drawString(font,Component.translatable("tile.machine_satlink.connected").append(": ").append(Component.translatable("tile.machine_satlink."+(link.connected?"yes":"no")).withStyle(link.connected?ChatFormatting.GREEN:ChatFormatting.RED)),x,y,0xffffff,true);y+=10;for(var info:link.info)if(info!=null){graphics.drawString(font,info,x,y,0xffffff,true);y+=10;}}
 private SatelliteLinkOverlay(){}
}
